  &DefaultButton;




function dir$dmxuatxu(p){
  this.constructor(p);
}
dir$dmxuatxu.prototype = new DirEvent();
dir$dmxuatxu.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmxuatxu.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()
	p.request('request_code_unit', '', '' , function(pp, d, run){
		if (run) {
			p.setDisabled('ma_xuatxu', true);
		}
	});
  dir$dmxuatxuDisabledMasterField(p, g);

}

function dir$dmxuatxuDisabledMasterField(p, g){
  if(p.valForm('ma_xuatxu').trim() != '') {
    p.setDisabled('ma_xuatxu', true);
  }
  else {
    p.setDisabled('ma_xuatxu', false);
  }
}






	.control-label.ma_xuatxu, .control-label.ten_xuatxu
	{	
		//font-weight:bold;	
		color: #499b98;;
	}







DECLARE @ma_unit VARCHAR(32);
SELECT @ma_unit = ma_unit FROM sysunit WHERE unit_id = @@unit;

SELECT @ma_unit + 'XX' + RIGHT('00000' + CAST(ISNULL(MAX(CAST(SUBSTRING(ma_xuatxu, LEN(@ma_unit) + 3, 10) AS INT)), 0) + 1 AS VARCHAR), 5) AS [!ma_xuatxu]
FROM dmxuatxu
WHERE ma_xuatxu LIKE @ma_unit + 'XX%';







if exists(select 1 from @@table a where [%whereFieldKey]) begin
  select '$codeExistsNewMsg' as message, '@@firstFieldKey' as field
  return
end

select @datetime0 = getdate(), @datetime2 = getdate(), @user_id0 = @@userId, @user_id2 = @@userId, @unit_id = @@unit






